        'Bitte einen Vorlagennamen mit maximal 150 Zeichen angeben.' => ['Enter a template name of at most 150 characters.', 'Saisissez un nom de modèle de 150 caractères maximum.', 'Introduzca un nombre de plantilla de hasta 150 caracteres.'],
        'Die Originalvorlage hat keinen Verein.' => ['The original template has no club.', 'Le modèle original n’a pas de club.', 'La plantilla original no tiene club.'],
        'Der Vorlagenname muss 3 bis 150 Zeichen enthalten.' => ['The template name must contain 3 to 150 characters.', 'Le nom du modèle doit contenir entre 3 et 150 caractères.', 'El nombre de plantilla debe tener entre 3 y 150 caracteres.'],
        'Keine geeigneten geplanten Kurstermine vorhanden.' => ['No suitable planned course sessions are available.', 'Aucune séance planifiée appropriée n’est disponible.', 'No hay sesiones planificadas adecuadas.'],
        'Die Terminplanung wurde gespeichert.' => ['Session planning was saved.', 'La planification a été enregistrée.', 'Se guardó la planificación de sesiones.'],
        'Bitte zuerst Kurstermine erzeugen.' => ['Please generate course sessions first.', 'Veuillez d’abord générer les séances de cours.', 'Genere primero las sesiones del curso.'],
        'Der Termin wurde ohne Buchungen dupliziert. Bitte Datum und Ausbildungseinheit prüfen.' => ['The session was duplicated without bookings. Please check the date and training unit.', 'La séance a été dupliquée sans réservations. Vérifiez la date et l’unité de formation.', 'Se duplicó la sesión sin reservas. Compruebe la fecha y la unidad de formación.'],
        'Der Ausbildungsplan der Zielqualifikation ist bereits vollständig im Kurs vorhanden.' => ['The target qualification’s training plan is already fully included in this course.', 'Le plan de formation de la qualification visée est déjà entièrement inclus dans le cours.', 'El plan de formación de la cualificación objetivo ya está completo en el curso.'],
        'Für den Ausbildungsplan sind bereits alle benötigten Kurstermine vorhanden.' => ['All required course sessions for the training plan already exist.', 'Toutes les séances nécessaires au plan de formation existent déjà.', 'Ya existen todas las sesiones necesarias para el plan de formación.'],
        'Der Kurs ist nicht abgeschlossen.' => ['The course is not completed.', 'Le cours n’est pas terminé.', 'El curso no está completado.'],
        'Der Kurs kann noch nicht abgeschlossen werden. Alle Teilnehmer müssen zuerst den Status "Bestanden", "Nicht bestanden" oder "Abgebrochen / storniert" besitzen.' => ['The course cannot be completed yet. All participants must first be marked Passed, Failed or Withdrawn / cancelled.', 'Le cours ne peut pas encore être terminé. Tous les participants doivent d’abord être marqués Réussi, Échoué ou Abandonné / annulé.', 'Aún no se puede completar el curso. Todos los participantes deben figurar como Aprobado, No aprobado o Abandonado / cancelado.'],
        'Der Kurs ist bereits abgeschlossen. Öffne ihn zuerst wieder, bevor Teilnehmer geändert werden.' => ['The course is completed. Reopen it before changing participants.', 'Le cours est terminé. Rouvrez-le avant de modifier les participants.', 'El curso está completado. Reábralo antes de cambiar participantes.'],
        'Für diesen Kurstermin sind noch keine Teilnehmer eingetragen. Verwende zuerst "Teilnehmer übernehmen".' => ['No participants are registered for this session. Use "Import participants" first.', 'Aucun participant n’est inscrit à cette séance. Utilisez d’abord « Importer les participants ».', 'No hay participantes inscritos en esta sesión. Use primero «Importar participantes».'],
        'Alle Teilnehmer wurden als anwesend markiert. Prüfe gegebenenfalls Abweichungen und speichere anschließend die Anwesenheit.' => ['All participants were marked present. Check any exceptions, then save attendance.', 'Tous les participants ont été marqués présents. Vérifiez les exceptions puis enregistrez les présences.', 'Todos los participantes se marcaron presentes. Compruebe las excepciones y guarde la asistencia.'],
        'Es wurden keine neuen Terminbuchungen angelegt. Alle aktiven Kursteilnehmer sind bereits für diesen Termin eingetragen.' => ['No new session bookings were created. All active course participants are already registered for this session.', 'Aucune réservation n’a été créée. Tous les participants actifs sont déjà inscrits à cette séance.', 'No se crearon nuevas reservas. Todos los participantes activos ya están inscritos en esta sesión.'],
        'Teilnehmer übernehmen' => ['Import participants', 'Importer les participants', 'Importar participantes'],
        'Der Kursteilnehmer ist keinem Kurs zugeordnet.' => ['The participant is not assigned to a course.', 'Le participant n’est affecté à aucun cours.', 'El participante no está asignado a un curso.'],
        'Dem Kursteilnehmer ist kein Mitglied zugeordnet.' => ['No member is assigned to the course participant.', 'Aucun membre n’est associé au participant.', 'No hay socio asignado al participante.'],
        'Der Teilnehmer hat diesen Kurs bereits bestanden.' => ['The participant has already passed this course.', 'Le participant a déjà réussi ce cours.', 'El participante ya ha aprobado este curso.'],
        'Der Kursabschluss ist gesperrt: Es sind keine vollständigen Pflichtanforderungen hinterlegt.' => ['Course completion is blocked: complete mandatory requirements have not been defined.', 'La validation du cours est bloquée : les exigences obligatoires complètes ne sont pas définies.', 'La finalización del curso está bloqueada: no se han definido requisitos obligatorios completos.'],
        'Dem Kurs ist keine Zielqualifikation zugeordnet.' => ['No target qualification is assigned to the course.', 'Aucune qualification visée n’est associée au cours.', 'No hay cualificación objetivo asignada al curso.'],
        'Kurs und Teilnehmer gehören nicht demselben Verein an.' => ['The course and participant do not belong to the same club.', 'Le cours et le participant n’appartiennent pas au même club.', 'El curso y el participante no pertenecen al mismo club.'],
        'Die Zielqualifikation gehört zu einem anderen Verein.' => ['The target qualification belongs to another club.', 'La qualification visée appartient à un autre club.', 'La cualificación objetivo pertenece a otro club.'],
        'Für diese Buchung ist kein Nachholtermin erforderlich.' => ['This booking does not require a make-up session.', 'Cette réservation ne nécessite pas de rattrapage.', 'Esta reserva no necesita recuperación.'],
        'Der ursprünglichen Buchung ist kein Mitglied zugeordnet.' => ['No member is assigned to the original booking.', 'Aucun membre n’est associé à la réservation initiale.', 'No hay socio asignado a la reserva original.'],
        'Der Nachholtermin muss sich vom ursprünglichen Kurstermin unterscheiden.' => ['The make-up session must differ from the original session.', 'La séance de rattrapage doit être différente de la séance initiale.', 'La sesión de recuperación debe ser distinta de la original.'],
        'Der Nachholtermin muss zum selben Kurs gehören.' => ['The make-up session must belong to the same course.', 'La séance de rattrapage doit appartenir au même cours.', 'La sesión de recuperación debe pertenecer al mismo curso.'],
        'Für diese Buchung wurde bereits ein Nachholtermin angelegt.' => ['A make-up session has already been created for this booking.', 'Une séance de rattrapage a déjà été créée pour cette réservation.', 'Ya se creó una sesión de recuperación para esta reserva.'],
        'Der Kurstermin ist keinem Kurs zugeordnet.' => ['The session is not assigned to a course.', 'La séance n’est associée à aucun cours.', 'La sesión no está asignada a un curso.'],
